; Entity: mou 1 (instance from template: tpl_1760115232795_f1eov)
ENTITY_MOU_1_ID EQU 0
ENTITY_MOU_1_COMP_MASK EQU #02  ; Component mask: 00000010b
ENTITY_MOU_1_TEMPLATE EQU "tpl_1760115232795_f1eov"
ENTITY_MOU_1_X EQU 16
ENTITY_MOU_1_Y EQU 8

; ==================================================================
; ENTITY MANAGEMENT FUNCTIONS
; ==================================================================

init_entities:
    ; Initialize all active game entities (1 entities)
    call init_mou_1
    ret

update_entities:
    ; Update all active entities (1 entities)
    call update_mou_1
    ret

init_mou_1:
    ; Initialize mou 1 at real position from JSON
    ; JSON position: (16, 8) tiles = (256, 128) pixels
    ; Template: tpl_1760115232795_f1eov
    ; Components: Sprite

    ; Set entity ID and component mask (DYNAMIC - based on template)
    ld a, 0             ; Entity ID
    ld b, #02              ; Component mask (00000010b)
    call create_entity         ; Create with actual components from template

    ; Set real position from JSON data
    ld hl, entity_x_pos
    ld e, 0             ; Entity index
    ld d, 0
    add hl, de
    ld (hl), 256         ; Set real X position from JSON

    ld hl, entity_y_pos
    add hl, de
    ld (hl), 128         ; Set real Y position from JSON

    ; Set sprite pattern and color
    ld hl, sprite_pattern
    add hl, de
    ld (hl), 0          ; Use entity index as sprite pattern

    ld hl, sprite_color
    add hl, de
    ld (hl), 15                ; White color

    ; Make sprite visible immediately
    ld a, 0             ; Sprite number
    ld b, 256            ; X position
    ld c, 128            ; Y position
    ld d, 0             ; Pattern
    ld e, 15                   ; Color
    call show_sprite
    ret

update_mou_1:
    ; Update mou 1 logic with real behavior
    ; Check if entity has input component (player entities)
    ld a, 0
    ld hl, entity_comp_masks
    ld e, a
    ld d, 0
    add hl, de
    ld a, (hl)
    and COMP_MASK_INPUT
    ret z                      ; Skip if no input component

    ; This is a player entity - update based on input
    ; Input velocity is already calculated in UPDATE_INPUT_COMPONENT
    ; Position update happens in UPDATE_POSITION_COMPONENT
    ret

